def aggregate_ticket_metrics(df, tags_list):
    grouped = df.groupby('priority', observed=False)['duration'].sum()
    summary = pd.Series([grouped.sum()], index=['total_time'])
    summary = pd.concat([summary, pd.Series([len(df)], index=['count'])], ignore_index=True)
    rows = [{'metric': 'total_time', 'value': summary.iloc[0]}, {'metric': 'count', 'value': summary.iloc[1]}]
    for tag in tags_list:
        tag_count = len(df[df['tags'].str.contains(tag, na=False)])
        rows.append({'metric': tag, 'value': tag_count})
    return pd.DataFrame(rows)

