    summaries = pd.DataFrame({'student': ['Initial'], 'score': [0.0]})
    for (student, group) in df.groupby('student'):
        avg = group['score'].mean()
        bonus = bonus_map.get(student, 0)
        summaries = summaries.append({'student': student, 'score': avg + bonus}, ignore_index=True)
    class_stats = df.groupby('class').mean()

