def process_crop_yields(df, historical_avg):

    def calc_relative(g):
        return (g['yield'] - g['yield'].mean()) / g['yield'].std()
    rel_yields = df.groupby('crop').apply(calc_relative, include_groups=False)
    yield_stats = pd.Series([rel_yields.mean()], index=['rel_mean'])
    yield_stats = pd.concat([yield_stats, pd.Series([historical_avg], index=['hist_avg'])], ignore_index=True)
    return np.vstack([yield_stats.values, [0.0, 1.0]])

